static int travel_group48(int map){for(int g=0;g<TRAVEL_GROUP_COUNT51;g++)for(int r=0;r<travelCounts48[g];r++)if(travelGroups48[g][r]==map)return g;return 0;}
static int travel_row51(int map){int g=travel_group48(map);for(int r=0;r<travelCounts48[g];r++)if(travelGroups48[g][r]==map)return r;return 0;}
static int travel_step48(int map,int delta){int g=travel_group48(map),n=travelCounts48[g];return travelGroups48[g][(travel_row51(map)+delta+n)%n];}
static int travel_region48(int map,int delta){return travelGroups48[(travel_group48(map)+delta+TRAVEL_GROUP_COUNT51)%TRAVEL_GROUP_COUNT51][0];}
